<section class="page-intro container-wide"><span class="eyebrow">GOOD CHOICES. GREAT FLAVOURS.</span><h1>Your basket.</h1></section><section class="container-wide pb-5"><?php if(!$totals['items']): ?><div class="empty-state"><span class="empty-icon">♧</span><h2>Your pantry is waiting.</h2><p>Add a jar of something delicious to get started.</p><a class="btn btn-primary" href="<?= e(url('shop')) ?>">Explore the pantry ↗</a></div><?php else: ?><div class="checkout-grid"><div><?php foreach($totals['items'] as $item): ?><article class="cart-item"><img src="<?= e(asset($item['image'])) ?>" alt="<?= e($item['name']) ?>"><div><a href="<?= e(url('product',['slug'=>$item['slug']])) ?>"><h3><?= e($item['name']) ?></h3></a><p><?= e($item['label']) ?> <?= $item['bundle_group']?'· Part of your combo':'' ?></p><strong><?= money($item['price']) ?></strong><?php if(!$item['product_active'] || !$item['variant_active'] || $item['stock']<$item['quantity']): ?><p class="text-danger">Availability changed. Please update your basket.</p><?php endif ?><form method="post" action="<?= e(url('cart/update')) ?>" class="cart-actions"><?= csrf() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><?php if(!$item['bundle_group']): ?><input class="form-control quantity" name="quantity" type="number" min="1" max="50" value="<?= $item['quantity'] ?>" aria-label="Quantity"><button name="action" value="update" class="text-button">Update</button><?php else: ?><span>Qty: <?= $item['quantity'] ?></span><?php endif ?><button class="text-button" name="action" value="remove"><?= $item['bundle_group']?'Remove combo':'Remove' ?></button></form></div><strong class="cart-line-total"><?= money($item['price']*$item['quantity']) ?></strong></article><?php endforeach ?><a class="text-link" href="<?= e(url('shop')) ?>">← Continue exploring</a></div><aside class="panel order-summary"><h2>The good stuff.</h2><?php require ROOT.'/app/Views/store/summary.php'; ?><form action="<?= e(url('cart/coupon')) ?>" method="post" class="coupon-form"><?= csrf() ?><label for="coupon">Have a little treat?</label><div class="input-group"><input id="coupon" class="form-control" name="coupon" placeholder="Coupon code" value="<?= e($totals['code']) ?>"><button class="btn btn-outline-primary">Apply</button></div><small class="muted">Clear the field and apply to remove a coupon.</small></form><?php if($totals['error']): ?><p class="text-danger"><?= e($totals['error']) ?></p><?php endif ?><a class="btn btn-primary w-100" href="<?= e(url('checkout')) ?>">Continue to checkout →</a><p class="small muted mt-3">Free shipping above <?= money(setting('free_shipping','79900')) ?> after discounts.</p></aside></div><?php endif ?></section>
